// @generated by tsrust api. This optional entry uses the application's TanStack cache.
import { queryOptions, mutationOptions, useQuery, useMutation, skipToken } from '@tanstack/react-query';
import { createClient, manifest, contractId } from './index.js';
import { freeze, own, validate } from './wire.js';

function settings(options, protectedFields) {
  if (options === undefined) return {};
  if (!options || typeof options !== 'object' || Array.isArray(options)) throw new TypeError('Expected TanStack options');
  for (const key of protectedFields) if (own(options, key)) throw new TypeError(`Tsrust owns ${key}`);
  return options;
}

function hasPrototypeField(schema) {
  const pending = [schema];
  while (pending.length) {
    const current = pending.pop();
    if (current.type === 'object') {
      if (own(current.properties, '__proto__')) return true;
      for (const child of Object.values(current.properties)) pending.push(child);
    } else if (current.type === 'array') pending.push(current.items);
    else if (current.type === 'tuple') for (const child of current.items) pending.push(child);
    else if (current.type === 'union') for (const child of current.members) pending.push(child);
  }
  return false;
}

export function createReactClient(transport, configuration) {
  const scope = configuration?.scope;
  if (typeof scope !== 'string' || scope.length === 0) throw new TypeError('A nonempty backend/user cache scope is required');
  validate({ type: 'string' }, scope, '', 'scope');
  const prefix = Object.freeze(['tsrust', scope, contractId]);
  const plain = createClient(transport);
  const client = Object.create(null);
  for (const operation of manifest.operations) {
    const names = operation.name.split('.');
    const leaf = names.pop();
    let namespace = client, source = plain;
    for (const name of names) { namespace = namespace[name] ||= Object.create(null); source = source[name]; }
    const invoke = source[leaf];
    const call = (input, options) => invoke(input, options);
    if (operation.kind === 'query') {
      const needsWholeResult = hasPrototypeField(operation.output);
      const prepare = input => freeze(validate(operation.input, input, operation.name, 'input'));
      // Validation emits fields in schema order. A serialized key preserves
      // __proto__ data fields that ordinary object-key sorting can otherwise lose.
      const key = input => Object.freeze([...prefix, operation.name, JSON.stringify(input === undefined ? null : input)]);
      call.key = input => key(prepare(input));
      call.queryOptions = (input, options) => {
        const checked = input === skipToken ? skipToken : prepare(input);
        const supplied = settings(options, ['queryKey', 'queryFn', 'queryHash', 'queryKeyHashFn']);
        if (needsWholeResult && supplied.structuralSharing === true) throw new TypeError('Wire __proto__ fields require structuralSharing:false or a custom sharing function');
        // Upstream's ordinary-object accumulator loses __proto__ fields during
        // structural sharing. Other schemas retain its normal sharing behavior.
        const sharing = needsWholeResult ? { structuralSharing: supplied.structuralSharing ?? false } : {};
        return queryOptions({ ...supplied, ...sharing, retry: supplied.retry ?? false, queryKey: checked === skipToken ? Object.freeze([...prefix, operation.name, '!skip']) : key(checked), queryFn: checked === skipToken ? skipToken : ({ signal }) => invoke(checked, { signal }) });
      };
      call.useQuery = function useOperationQuery(input, options, queryClient) {
        return useQuery(call.queryOptions(input, options), queryClient);
      };
    } else {
      call.mutationOptions = options => {
        const supplied = settings(options, ['mutationKey', 'mutationFn']);
        return mutationOptions({ ...supplied, retry: supplied.retry ?? false, mutationKey: Object.freeze([...prefix, operation.name]), mutationFn: async (input, context) => {
          const result = await invoke(input);
          // ponytail: refresh this client scope. Add operation dependency metadata
          // only if measurements show that these broad refreshes are costly.
          // A failed cache refresh must not turn an acknowledged write into a
          // retryable mutation failure. Observers retain their own query errors.
          await context.client.invalidateQueries({ queryKey: prefix }, { throwOnError: false }).catch(() => {});
          return result;
        } });
      };
      call.useMutation = function useOperationMutation(options, queryClient) {
        return useMutation(call.mutationOptions(options), queryClient);
      };
    }
    namespace[leaf] = Object.freeze(call);
  }
  return freeze(client);
}
